 where startswith(RECORD_SOURCE, 'MAXIMUS_') and (QUOTE_HKEY is null or nullif(trim(PARENT_BK), '') is null or regexp_like(trim(PARENT_BK), '^[:#|].*|.*[:#|]$'))
union all
